    methodologyPara1: "ブランドのサステナビリティチームから、FUZE の F3 と F4 における主効力試験が AATCC 100 ではなく ASTM E2149 で報告される理由について質問を受けることがあります。簡潔に言えば、ASTM E2149 は非溶出型接触殺菌化学に合わせて設計された動的接触試験だからです。本試験は細菌細胞とメタマテリアル結合繊維表面の直接物理接触を評価対象とします — これはまさに FUZE のメカニズムそのものです。",
